module fsm (
	input clk,
	input reset,
	input e,
	input f,
	output reg k);

	parameter T=0, U=1, S1=2, S2=3, S3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= T;
		else state <= next;
	end

	always_comb begin
		case (state)
			T: next = e ? U : T;
			U: next = f ? S1 : S2;
			S1: next = f ? S2 : S3;
			S2: next = f ? S3 : T;
			S3: next = e ? U : T;
			default: next = 'x;
		endcase
	end

	assign k = (state == S1);

endmodule

