description:
Implement a 4-to-2 priority encoder that takes a 4-bit input signal, D, and produces a 2-bit output signal, Y, representing the binary value of the highest-priority active input. The encoder prioritizes inputs from D[3] to D[0], where a higher bit has greater priority. The output Y will indicate the index of the highest set bit; if no bits are set, Y defaults to 0. The output Y is registered to synchronize with a clock edge, ensuring stable output.
module top_module(
    input [3:0] D,
    input clk,       // Added clk input to fix the error
    output reg [1:0] Y
);

code:
module top_module(
    input [3:0] D,
    input clk,       // Added clk input to fix the error
    output reg [1:0] Y
);reg [1:0] Y_reg;

    always @(*) begin
        Y_reg[1] = D[3];
        if (D[3] == 1) begin
            Y_reg[0] = 0;
        end else if (D[2] == 1) begin
            Y_reg[0] = 1;
        end else if (D[1] == 1) begin
            Y_reg[0] = 0;
        end else if (D[0] == 1) begin
            Y_reg[0] = 1;
        end else begin
            Y_reg[0] = 0;
        end
    end

    always @(posedge clk) begin
        Y <= Y_reg;
    end
endmodule

