module up_down_counter_12bit(
    input clk,
    input reset,
    input dir,
    output reg [11:0] count
);

always @(posedge clk or posedge reset) begin
    if (reset)
        count <= 12'b0;
    else if (dir)
        count <= count + 1;
    else
        count <= count - 1;
end

endmodule

