module async_down_counter(
    input clk,
    input rst,
    output reg [9:0] q
    );

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q <= 10'b1111111111;
        end else begin
            q <= q - 1;
        end
    end
endmodule

