description:
Design a glitch filter circuit that removes short-duration spurious signals from the input. The module employs a shift register with a configurable delay line to hold the input signal, ensuring that only signals sustained for at least a specified duration (determined by the parameter `glitch_duration`) are passed to the output. When the input signal transitions from high to low while being held high for less than the glitch duration, the module outputs the last stable state; otherwise, it outputs the current input state, effectively filtering out glitches.
module top_module(
  input signal_in,
  output signal_out
);

code:
module top_module(
  input signal_in,
  output signal_out
);parameter glitch_duration = 4; // minimum pulse duration

reg [glitch_duration-1:0] delay_line;
reg filtered_signal;

always @(posedge signal_in) begin
  delay_line <= {delay_line[glitch_duration-2:0], signal_in};
  if (delay_line[0] == 1'b1 && delay_line[glitch_duration-1] == 1'b0) begin
    filtered_signal <= delay_line[glitch_duration-2];
  end else begin
    filtered_signal <= signal_in;
  end
end

assign signal_out = filtered_signal;

endmodule

