module top_module(
	data,
	rdclk,
	rdreq,
	wrclk,
	wrreq,
	q,
	rdempty,
	wrfull);input	[31:0]  data;
	input	  rdclk;
	input	  rdreq;
	input	  wrclk;
	input	  wrreq;
	output	[31:0]  q;
	output	  rdempty;
	output	  wrfull;

	reg [31:0] mem [0:3];
	reg wr_ptr = 0;
	reg rd_ptr = 0;
	wire wr_en = !wrfull && wrreq;
	wire rd_en = !rdempty && rdreq;

	assign q = mem[rd_ptr];
	assign rdempty = (wr_ptr == rd_ptr) && !wr_en;
	assign wrfull = (wr_ptr == (rd_ptr + 4'h1)) && !rd_en;

	always @(posedge wrclk) begin
		if (wr_en) begin
			mem[wr_ptr] <= data;
			wr_ptr <= wr_ptr + 4'h1;
		end
	end

	always @(posedge rdclk) begin
		if (rd_en) begin
			rd_ptr <= rd_ptr + 4'h1;
		end
	end

endmodule

