module top_module(charStatus , enable , clk);output charStatus;
    input enable , clk;
    reg [3:0] bitCount;

	always @(posedge enable) 
	begin
		bitCount = 4'b0000;
	end

	always @(posedge clk)
	begin
		if(bitCount < 9)
		begin
			bitCount = bitCount + 1;
		end
		else
		begin
			bitCount = 4'b0000;
		end
	end

	assign charStatus = bitCount[0] & ~bitCount[1] & ~bitCount[2] & bitCount[3];endmodule

