    input clk,
    input reset,
    output reg [3:0] count
);reg [3:0] count_reg1;
reg [3:0] count_reg2;

always @(posedge clk) begin
    if (reset) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
    end
    else begin
        count_reg1 <= count;
        count_reg2 <= count_reg1;
    end
end

always @(*) begin
    if (reset) begin
        count <= 4'b0;
    end
    else begin
        count <= count_reg2 + 4'b1;
    end
end

endmodule

module top_module(
    A   ,
    B   ,
    C   ,
    D   ,
    S0  ,
    S1  ,
    Y   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);output Y   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D   ;
    input  S0  ;
    input  S1  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    assign Y = (S1 & S0) ? D :
               (S1 & ~S0) ? C :
               (~S1 & S0) ? B :
               A;

endmodule

module top_module(clk,rst,clk4096);input  rst,clk;
 output clk4096;
 reg [11:0] q;

always@(posedge clk or negedge  rst)
begin
  if(rst==0)
    q<=12'b0000_0000_0000;
  else begin
    if(q==12'b1111_1111_1111) 
	 q<=12'b0000_0000_0000;
	 else
	 q<=q+1;
	 end
end

assign clk4096= q[11];

endmodule

