module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);reg [3:0] reg1, reg2, reg3, reg4;
    reg [1:0] counter;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            reg1 <= 4'b0;
            reg2 <= 4'b0;
            reg3 <= 4'b0;
            reg4 <= 4'b0;
            counter <= 2'b0;
        end else begin
            if (load & ena) begin
                reg1 <= data;
                reg2 <= 4'b0;
                reg3 <= 4'b0;
                reg4 <= 4'b0;
                counter <= 2'b0;
            end else if (ena) begin
                counter <= counter + 1;
                case (counter)
                    2'b00: begin
                        reg1 <= data;
                        reg2 <= reg1;
                    end
                    2'b01: begin
                        reg2 <= reg1;
                        reg3 <= reg2;
                    end
                    2'b10: begin
                        reg3 <= reg2;
                        reg4 <= reg3;
                    end
                    2'b11: begin
                        reg4 <= reg3;
                    end
                endcase
            end
        end
    end

    assign q = (counter == 2'b00) ? reg1 :
               (counter == 2'b01) ? reg2 :
               (counter == 2'b10) ? reg3 :
               (counter == 2'b11) ? reg4 : 4'b0;

endmodule

