module top_module(
    input wire clk,       // Clock signal
    input wire [7:0] A,   // 8-bit input A
    input wire [7:0] B,   // 8-bit input B
    input wire S,         // Control input for subtraction
    output reg [7:0] C,   // 8-bit output C
    output reg carry_out, // Carry out signal
    output reg overflow   // Overflow signal
);always @ (posedge clk) begin
        if (S == 1) begin
            // Subtraction
            C <= A - B;
            carry_out <= A < B;
            overflow <= (A[7] != B[7]) && (C[7] != A[7]);
        end else begin
            // Addition
            C <= A + B;
            carry_out <= C[8];
            overflow <= (A[7] == B[7]) && (C[7] != A[7]);
        end
    end

endmodule

