    input clk,
    input Up,
    input Down,
    input Load,
    input Reset,
    output reg [2:0] Q
);reg [2:0] Q_reg1, Q_reg2;

always @(posedge clk) begin
    if (Reset) begin
        Q_reg1 <= 3'b0;
        Q_reg2 <= 3'b0;
    end
    else begin
        Q_reg1 <= Q_reg2;
        Q_reg2 <= Q;
    end
end

always @(*) begin
    if (Load) begin
        Q = 3'b0;
    end
    else if (Up) begin
        Q = Q_reg1 + 1;
    end
    else if (Down) begin
        Q = Q_reg1 - 1;
    end
    else begin
        Q = Q_reg1;
    end
end

endmodule

