module top_module(input a,b,cin,
 output reg s,c);reg t1,t2;

always @ (a,b,cin)
begin 
	t1=a^b;
	s=t1^cin;
	t2= a&b|b&cin;
	c=t2|cin&a;
end
endmodule

module top_module(input wire [31:0] pulse_width, input wire [31:0] pulse_period, input wire clk, input wire rst_n, output wire pwm_out );reg d, q;
reg [31:0] count_q,count_d;

assign rst = ~rst_n;

always @ (*)
begin
	count_d = count_q + 1'b1; 
	if (count_q > pulse_period)
		count_d = 0;
	d = (count_d< pulse_width)?1'b1:1'b0;
end

always @ (posedge clk)
begin
	if (rst) 
	begin
		count_q <= 32'b0;
	end 
	else 
	begin
		count_q <= count_d;
	end
	q<=d;
end

assign pwm_out = q;

endmodule

